const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function highlightsHTML(job){
  if(!job||typeof job!=='object'||!job.highlights)return '';
  const groups=[['responsibilities','Responsibilities'],['requirements','Required experience & qualifications'],['preferred','Preferred qualifications'],['skills','Skills & tools mentioned'],['compensation','Compensation & benefits']];
  const fields=[['Role',job.role],['Company',job.company],['Location',job.location],['Employment type',job.employmentType],['Posted',job.datePosted],['Closing date',job.validThrough]];
  return `<section class="panel jd-highlights"><span class="eyebrow">FROM THE JOB POSTING</span><h2 class="section-label">Job description highlights</h2><p class="help">Extracted from the posting using ${escape(job.method||'page text')}. Review against the original; details absent from the page are not inferred.</p><dl class="jd-facts">${fields.filter(([,v])=>typeof v==='string'&&v.trim()).map(([k,v])=>`<div><dt>${k}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl><div class="jd-groups">${groups.map(([key,title])=>{const entries=Array.isArray(job.highlights[key])?job.highlights[key].filter(v=>typeof v==='string').slice(0,30):[];return `<div><h4>${title}</h4>${entries.length?`<ul>${entries.map(t=>`<li>${escape(t)}</li>`).join('')}</ul>`:'<p class="help">Not identified in the posting.</p>'}</div>`;}).join('')}</div><p class="help">Imported ${escape(job.parsedAt?new Date(job.parsedAt).toLocaleString():'')} · No AI API used</p></section>`;
}
